WITH seed AS(SELECT n,(n*7919)%10000 k,CASE WHEN n%100=0 THEN 200001-n ELSE n END clock_key FROM generate_series(1,200000)n),scoped AS(SELECT *,jsonb_build_object('game_union_id',CASE WHEN k>=2660 AND k<9718 THEN 'fade0000-0000-0000-0000-000000000001' END,'host_club_id',NULL,'tournament_id',NULL,'is_private',false,'asset','chips','unit_scale',CASE WHEN k>=2660 AND k<9718 THEN 1 ELSE 1+k%3 END)scope FROM seed),e AS(SELECT *,CASE WHEN k<2700 THEN '{}'::jsonb ELSE jsonb_build_object('status','ready','basis_certified',true,'all_players_included',true,'game_scope',scope)END base FROM scoped) INSERT INTO public.union_pnl_cash_outcomes SELECT 'fade0000-0000-0000-0000-000000000010',n,('fade0000-0000-0000-0001-'||lpad(n::text,12,'0'))::uuid,'1'::xid8,CASE WHEN clock_key>160000 THEN '2026-10-20'::timestamptz ELSE '2026-09-01'::timestamptz END+clock_key*interval '1 microsecond',md5(n::text)||md5('hash'||n::text),scope,base||jsonb_build_object('padding',repeat('x',greatest(0,1275-124-pg_column_size(scope)-pg_column_size(base)-16))) FROM e;
